import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(0, 3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Create sprite plane with billboard effect
  const spriteTexture = ctx.textureLoader.load(config.assets.imageUrl);
  const planeGeometry = new THREE.PlaneGeometry(0.8, 0.5);

  const planeMaterial = new MeshBasicNodeMaterial({
    map: texture(spriteTexture),
    transparent: true,
    side: THREE.DoubleSide
  });

  const spriteMesh = new THREE.Mesh(planeGeometry, planeMaterial);
  group.add(spriteMesh);

  // Render text content via fontAtlas
  if (config.textContent && ctx.fontAtlas) {
    const textContent = config.textContent[0] || 'Journal';
    const textMesh = ctx.fontAtlas.createMesh(textContent, {
      size: 0.34,
      weight: 400,
      font: 'Lora',
      color: 0x16161d
    });
    if (textMesh) {
      group.add(textMesh);
    }
  }

  // Setup billboarding to face camera
  if (ctx.camera) {
    group.onBeforeRender = (renderer, scene, camera) => {
      group.lookAt(camera.position);
    };
  }

  // Cleanup resources on dispose
  group.userData.cleanup = () => {
    group.traverse((child) => {
      if (child.geometry) {
        child.geometry.dispose();
      }
      if (child.material) {
        if (child.material.map) {
          child.material.map.dispose();
        }
        child.material.dispose();
      }
    });
    gsap.killTweensOf(group);
  };

  return group;
}
